SourceCode.Declaration:
/// <summary>
/// CB166_SalesOrderSubstitutes
/// Process substitution for customer with substitutions enabled
/// </summary>
class METSubstitutionSalesLineProcess_Enabled extends METSubstitutionSalesLineProcess
{    
}

Method.Source:
/// <summary>
/// For customers with substitutions enabled
/// We don't check if there was a previous substitution or not, cancel current line and create a new line
/// by copying most of the values from the line being cancelled above, excluding price.
/// </summary>
/// <returns>True if there was a substitution; otherwise, false.</returns>
protected boolean substitute()
{
    boolean ret = true;        
    
    // For customers who have “Substitutions enabled” = Yes, cancel current line and create a new line
    this.cancelAndCopyToNewLine(salesLine);

    return ret;
}

/// <summary>
/// This is not applicable for “Substitutions enabled” = Yes as we are not checking for previous substitutions
/// </summary>
/// <returns>Reason code when no previous substitute</returns>
protected ReasonCode setNoPreviousSubReasonCode()
{    
    return METConstants::emptyString;
}

/// <summary>
/// This is not applicable for “Substitutions enabled” = Yes as we are not creating a new cancelled line with a reason code
/// </summary>
/// <returns>Reason code for the new sales order line</returns>
protected ReasonCode setNewLineReasonCode()
{
    return METConstants::emptyString;
}

/// <summary>
/// Set substitution type to SubstitutionCode
/// </summary>
/// <returns>Substitution type</returns>
protected METSalesItemSubstitutionType setSubstitutionType()
{
    return METSalesItemSubstitutionType::SubstitutionCode;
}

/// <summary>
/// Set item number for the new line from the substitute item
/// </summary>
/// <param name = "_substitutionType">Substitution type</param>
/// <param name = "_substituteOriginalItemID">Substitute original item id</param>
/// <returns>Item id for the new sales order line</returns>
protected ItemId setItemId(METSalesItemSubstitutionType _substitutionType, METSubstituteOriginalItemID _substituteOriginalItemID)
{
    // The “substitute item” of the active “sales item substitutes” record
    return salesItemSubstitute.SubstituteItemId;
}

/// <summary>
/// Update indicators to add 'S'
/// </summary>
/// <param name = "_metSalesLine">Custom new sales order line</param>
protected void updateIndicators(METSalesLine _metSalesLine)
{
    // Add S indicator if not already in there
    _metSalesLine.addIndicator(METConstants::S);
}

    /// <summary>
    /// Set original item number for the new line
    /// </summary>
    /// <param name = "_substitutionType">Substitution type</param>
    /// <param name = "_substituteOriginalItemID">Substitute original item id</param>
    /// <returns>Substitute original item id</returns>
    protected METSubstituteOriginalItemID setOriginalItemId(METSalesItemSubstitutionType _substitutionType, METSubstituteOriginalItemID _substituteOriginalItemID)
    {
        // default to the Item Number of the sales line just cancelled.
        METSubstituteOriginalItemID itemId = salesLine.ItemId;
        
        // If a previous substitution has been applied to the line just cancelled (Substitution type is not <blank>) and “Substitution type” <> “Parent/child substitute“:
        if (_substitutionType != METSalesItemSubstitutionType::None
        &&  _substitutionType != METSalesItemSubstitutionType::ParentChild)
        {
            // Set Item number = The “Original item” of the sales line just cancelled.
            //itemId = _metSalesLine.SubstituteOriginalItemID;
            itemId = _substituteOriginalItemID;
        }

        //_metSalesLineNew.SubstituteOriginalItemID = itemId;
        return itemId;
    }

/// <summary>
/// This is not applicable for “Substitutions enabled” = No as we are not substituting item number for the new line
/// </summary>
/// <returns>Substitute item ID</returns>
protected METSubstituteItemID setSubstituteItemID()
{
    return METConstants::emptyString;
}

/// <summary>
/// Indicate if the new sales order line must be cancelled or not
/// </summary>
/// <returns>boolean to cancel new sales line</returns>
protected boolean cancelNewLine()
{
    return false;
}
